-- Reprise de l'unique compte d'avant.
--
-- Écrit à la main, et CONDITIONNÉ à l'existence du jeton : sur une base qui
-- n'a jamais connecté Instagram — le cas de toutes les bases de test — ce
-- bloc ne fait rien.
--
-- Ni la ligne `secret` d'origine ni le réglage `instagram_public` ne sont
-- supprimés : l'ancien conteneur tourne encore pendant le déploiement et les
-- lit. Ils deviennent inertes ; une migration ultérieure pourra les retirer.
DO $$
DECLARE
  profil jsonb := (SELECT value FROM setting WHERE key = 'instagram_public');
  technique jsonb := (SELECT value FROM setting WHERE key = 'instagram');
  compte integer;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM secret WHERE key = 'instagram_access_token') THEN
    RETURN;
  END IF;

  INSERT INTO social_account (
    network, external_id, username, display_name, biography, avatar_url, followers, media_count
  ) VALUES (
    'instagram',
    nullif(technique ->> 'accountId', ''),
    nullif(ltrim(coalesce(profil ->> 'handle', ''), '@'), ''),
    profil ->> 'name',
    profil ->> 'biography',
    profil ->> 'avatar',
    (profil ->> 'followers')::integer,
    (profil ->> 'posts')::integer
  ) RETURNING id INTO compte;

  -- Le jeton devient celui DU compte : une clé par compte.
  INSERT INTO secret (key, ciphertext, updated_at)
  SELECT 'instagram_access_token:' || compte, ciphertext, updated_at
  FROM secret WHERE key = 'instagram_access_token';

  UPDATE social_post SET account_id = compte WHERE network = 'instagram';
END $$;
